package kr.releasepilot.controlplane.shared.config;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.slf4j.MDC;import org.springframework.core.Ordered;import org.springframework.core.annotation.Order;import org.springframework.stereotype.Component;import java.io.IOException;import java.util.UUID;
@Component @Order(Ordered.HIGHEST_PRECEDENCE)public class CorrelationIdFilter implements Filter{public static final String HEADER="X-Correlation-ID";public static final String MDC_KEY="correlationId";@Override public void doFilter(ServletRequest request,ServletResponse response,FilterChain chain)throws IOException,ServletException{var http=(HttpServletRequest)request;String value=http.getHeader(HEADER);try{value=value==null?UUID.randomUUID().toString():UUID.fromString(value).toString();}catch(IllegalArgumentException invalid){value=UUID.randomUUID().toString();}((HttpServletResponse)response).setHeader(HEADER,value);try(MDC.MDCCloseable ignored=MDC.putCloseable(MDC_KEY,value)){chain.doFilter(request,response);}}public static UUID current(){String value=MDC.get(MDC_KEY);return value==null?UUID.randomUUID():UUID.fromString(value);}}
